    white-space: nowrap;
}

.linguamark-directory-empty {
    margin: 8px;
    color: var(--fg-faint);
    font-size: 13px;
}

#write.linguamark-empty-viewer {
    display: grid;
    min-height: calc(100vh - 106px);
    place-items: center;
}

.linguamark-empty-viewer-home {
    display: grid;
    width: min(720px, 100%);
    gap: 20px;
}

.linguamark-empty-viewer-message {
    max-width: 520px;
    justify-self: center;
    padding: 30px;
    border: 1px dashed rgba(74, 124, 89, 0.3);
    border-radius: var(--radius-lg);
    background: var(--bg-soft);
    color: var(--fg-muted);
    text-align: center;
}

.linguamark-empty-viewer-message p {
    margin: 8px 0 0;
}

.linguamark-empty-viewer-title {
    color: var(--accent-deep);
    font-size: 22px;
    font-weight: 700;
}

.linguamark-empty-viewer-library {
    font: 15px/1.5 var(--font-body);
    text-align: left;
}

#write .linguamark-empty-viewer-library .linguamark-markdown-library-section h3 {
    margin: 0 0 12px;
    color: var(--accent-deep);
    font: 700 15px/1.35 var(--font-heading);
    letter-spacing: normal;
}

#write .linguamark-empty-viewer-library .linguamark-markdown-library-section h3::before {
    content: none;
}

#write .linguamark-empty-viewer-library .linguamark-markdown-library-list {
    padding: 0;
}

#write .linguamark-empty-viewer-library .linguamark-markdown-library-list > li {
    margin: 0;
}

#write.linguamark-directory-image-preview {
    display: grid;
    min-height: calc(100vh - 106px);
    place-items: center;
}

#write.linguamark-directory-image-preview figure {
    width: 100%;
    margin: 0;
}

#write.linguamark-directory-image-preview img {
    max-width: 100%;
    max-height: calc(100vh - 180px);
    object-fit: contain;
}

#write .linguamark-directory-image-loading {
    min-height: 120px;
    background: var(--bg-soft);
}

#write .linguamark-directory-image-error {
    min-height: 80px;
    padding: 16px;
    border: 1px dashed rgba(196, 86, 74, 0.45);
    box-shadow: none;
}

#write .linguamark-directory-link-disabled {
    color: var(--fg-faint);
    border-bottom-style: dashed;
    cursor: not-allowed;
}

.linguamark-markdown-toc-backdrop {
    display: none;
}

#write :is(h1, h2, h3, h4, h5, h6) {
    scroll-margin-top: 18px;
}

body.linguamark-markdown-page #write {
    box-sizing: border-box;
    width: min(980px, calc(100% - 48px));
    max-width: none;
}

body.linguamark-markdown-page.linguamark-full-width #write {
    width: 100%;
}

#write pre > code {
    display: block;
    padding: 0;
    border: 0;
    background: transparent;
    color: inherit;
    font-size: inherit;
}

#write .contains-task-list,
#write .task-list {
    padding-left: 0;
    list-style: none;
}

#write .footnote-ref a,
#write .footnote-backref {
    color: var(--accent-deep);
    border-bottom: 0;
    font-weight: 700;
    text-decoration: none;
}

#write .footnotes {
    margin-top: 2em;
    padding-top: 0.8em;
    border-top: 1px solid var(--accent-soft);
    color: var(--fg-muted);
    font-size: 0.88em;
}

#write .footnotes-sep {
    display: none;
}

#write .md-toc-content ul {
    margin: 0;
    padding-left: 1.2em;
}

#write .md-toc-content li {
    margin: 0.2em 0;
}

#write .md-math-block > eqn,
#write .md-math-block > .katex-display {
    display: block;
    margin: 0;
}

#write .md-inline-math {
    display: inline-block;
}

#write .hljs-keyword,
#write .hljs-selector-tag,
#write .hljs-literal,
#write .hljs-section,
#write .hljs-link {
    color: var(--cm-keyword);
}

#write .hljs-string,
#write .hljs-title,
#write .hljs-name,
#write .hljs-type,
#write .hljs-attribute,
#write .hljs-symbol,
#write .hljs-bullet,
#write .hljs-addition,
#write .hljs-variable,
#write .hljs-template-tag,
#write .hljs-template-variable {
    color: var(--cm-string);
}

#write .hljs-comment,
#write .hljs-quote,
#write .hljs-deletion,
#write .hljs-meta {
    color: var(--cm-comment);
}

#write .hljs-number,
#write .hljs-regexp,
#write .hljs-built_in,
#write .hljs-builtin-name,
#write .hljs-params {
    color: var(--cm-number);
}

#write .hljs-function,
#write .hljs-title.function_,
#write .hljs-class .hljs-title {
    color: var(--cm-def);
}

#write .hljs-attr,
#write .hljs-property {
    color: var(--cm-property);
}

#write .linguamark-mermaid-source[data-render-error="true"] {
    border-color: #c4564a;
}

#write iframe {
    max-width: 100%;
    border: 1px solid rgba(74, 124, 89, 0.2);
    border-radius: var(--radius);
}

.linguamark-markdown-error {
    position: fixed;
    top: 16px;
    left: 50%;
    z-index: 2147483646;
    max-width: min(560px, calc(100vw - 32px));
    padding: 10px 14px;
    border: 1px solid rgba(196, 86, 74, 0.35);
    border-radius: var(--radius);
    background: #f6e9e7;
    box-shadow: var(--shadow);
    color: #8a3a31;
    font: 14px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    transform: translateX(-50%);
}

@media (max-width: 900px) {
    .linguamark-markdown-toc-resizer {
        display: none;
    }

    .linguamark-markdown-shell,
    body.linguamark-markdown-page:not(.linguamark-toc-open) .linguamark-markdown-shell {
        display: block;
    }

    .linguamark-markdown-toc {
        position: fixed;
        top: 58px;
        bottom: 0;
        left: 0;
        z-index: 2147482999;
        width: min(320px, 86vw);
        height: auto;
        margin: 0;
        border-width: 0 1px 0 0;
        border-radius: 0 var(--radius-lg) var(--radius-lg) 0;
        transform: translateX(-100%);
    }

    body.linguamark-markdown-page.linguamark-toc-open .linguamark-markdown-content {
        overflow: hidden;
    }

    body.linguamark-markdown-page.linguamark-toc-open .linguamark-markdown-toc {
        visibility: visible;
        opacity: 1;
        pointer-events: auto;
        transform: translateX(0);
    }

    .linguamark-markdown-toc-backdrop {
        position: fixed;
        inset: 58px 0 0;
        z-index: 2147482998;
        display: block;
        width: 100%;
        height: auto;
        padding: 0;
        border: 0;
        background: rgba(31, 42, 35, 0.26);
        backdrop-filter: blur(2px);
        cursor: pointer;
    }

    .linguamark-markdown-toc-backdrop[hidden] {
        display: none;
    }
}

@media (max-width: 700px) {
    .linguamark-markdown-library {
        width: calc(100vw - 24px);
        height: calc(100vh - 24px);
        min-width: 0;
        min-height: 0;
        max-width: calc(100vw - 24px);
        max-height: calc(100vh - 24px);
        resize: none;
    }

    .linguamark-markdown-library-panel {
        padding: 18px;
    }

    .linguamark-markdown-library-grid {
        grid-template-columns: minmax(0, 1fr);
    }

    .linguamark-markdown-library-panel .linguamark-markdown-library-grid {
        grid-template-rows: repeat(2, minmax(0, 1fr));
    }

    body.linguamark-markdown-page #write {
        width: 100%;
        margin: 0;
        padding: 28px 22px 64px;
        border-radius: 0;
        box-shadow: none;
    }
}

#write .json-tree {
    padding: 20px;
    overflow-x: auto;
    border-radius: var(--radius);
    background: var(--code-bg);
    color: var(--code-fg);
    font-family: var(--font-mono);
    font-size: 14px;
    line-height: 1.7;
    white-space: pre;
    tab-size: 2;
}

#write .json-tree summary {
    cursor: pointer;
    width: fit-content;
}

#write .json-tree summary:focus-visible {
    outline: 2px solid var(--cm-def);
    outline-offset: 2px;
}

#write .json-children {
    padding-left: 2ch;
    border-left: 1px solid var(--code-line);
}

#write .json-tree details[open] > summary > .json-collapsed {
    display: none;
}

#write .json-key { color: var(--cm-def); }
#write .json-string { color: var(--cm-string); }
#write .json-number { color: var(--cm-number); }
#write .json-literal { color: var(--cm-keyword); }
#write .linguamark-json-error { color: var(--accent-deep); }

@media (prefers-reduced-motion: reduce) {
    html.linguamark-reload-scroll-animation .linguamark-markdown-content {
        scroll-behavior: auto;
    }

    .linguamark-markdown-shell,
    .linguamark-markdown-toc {
        transition: none;
    }
}
